def load():
    import glob
    import pandas as pd
    files = sorted(glob.glob('data/environment/input/*beach_datasheet.csv'))
    dfs = []
    for f in files:
        try:
            df = pd.read_csv(f)
        except Exception:
            df = pd.read_csv(f, encoding='latin-1')
        df['source_file'] = f.split('/')[-1]
        dfs.append(df)
    if not dfs:
        return pd.DataFrame()
    out = pd.concat(dfs, ignore_index=True)
    return out

def load() -> pd.DataFrame:
    import glob, os, re
    files = sorted(glob.glob('data/environment/input/*beach_datasheet.csv'))
    rows = []
    for path in files:
        try:
            head = pd.read_csv(path, header=None, nrows=20, dtype=str, engine='python')
        except Exception:
            head = pd.read_csv(path, header=None, nrows=20, dtype=str, encoding='latin-1', engine='python')
        header_row = None
        for i in range(len(head)):
            if head.iloc[i].astype(str).str.contains('Date', case=False, na=False).any():
                header_row = i
                break
        if header_row is None:
            continue
        site_names = None
        if header_row-1 >= 0:
            site_names = head.iloc[header_row-1].fillna('').astype(str).tolist()
        try:
            df = pd.read_csv(path, header=header_row, dtype=str, engine='python')
        except Exception:
            df = pd.read_csv(path, header=header_row, dtype=str, encoding='latin-1', engine='python')
        cols = list(df.columns)
        # find date and 1-day rain columns
        date_col = next((c for c in cols if 'date' in str(c).lower()), None)
        rain1_col = next((c for c in cols if '1' in str(c).lower() and 'day' in str(c).lower() and 'rain' in str(c).lower()), None)
        for i in range(len(cols)-1):
            c1 = cols[i]
            c2 = cols[i+1]
            if ('tag' in str(c1).lower()) and ('enter' in str(c2).lower()):
                site = site_names[i] if site_names is not None and site_names[i] not in [None, ''] else os.path.basename(path).replace('_datasheet.csv','')
                sub = pd.DataFrame()
                sub['date'] = df[date_col] if date_col in df.columns else df.iloc[:,0]
                if rain1_col and rain1_col in df.columns:
                    sub['rain_1day'] = df[rain1_col]
                else:
                    sub['rain_1day'] = None
                sub['site'] = site
                sub['enterococcus_raw'] = df[c2]
                sub['source_file'] = os.path.basename(path)
                rows.append(sub)
    if not rows:
        return pd.DataFrame(columns=['total_failed','failed_with_rain','percent_rain_given_failed'])
    long = pd.concat(rows, ignore_index=True)
    # clean enterococcus: remove non-numeric except dot
    long['enterococcus'] = pd.to_numeric(long['enterococcus_raw'].astype(str).str.replace('[^0-9.]','', regex=True), errors='coerce')
    # clean rain
    long['rain_1day_num'] = pd.to_numeric(long['rain_1day'].astype(str).str.replace('[^0-9.]','', regex=True), errors='coerce').fillna(0.0)
    # consider only samples with enterococcus measured
    measured = long[~long['enterococcus'].isna()].copy()
    failed = measured[measured['enterococcus'] > 104]
    if len(failed) == 0:
        return pd.DataFrame([{'total_failed':0,'failed_with_rain':0,'percent_rain_given_failed':0.0}])
    failed_with_rain = failed[failed['rain_1day_num'] > 0]
    total_failed = len(failed)
    failed_rain_count = len(failed_with_rain)
    percent = round(failed_rain_count / total_failed * 100, 2)
    return pd.DataFrame([{'total_failed': total_failed, 'failed_with_rain': failed_rain_count, 'percent_rain_given_failed': percent}])
